HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
ROOT = PHASE.parents[1]
need, read, sha = runner.require, runner.read, runner.sha
MASK64 = (1 << 64) - 1


def evidence(path):
    path = Path(path).resolve(strict=True)
    return {'path': str(path.relative_to(ROOT)) if path.is_relative_to(ROOT) else str(path), 'sha256': sha(path)}


def class_hashes(root):
    return {p.relative_to(root).as_posix(): sha(p) for p in sorted(root.rglob('*.class'))}


def direct_oracle(args):
    """Independent fixed-fixture oracle using complete short strings and scalar Java hash arithmetic."""
    need(args['width'] == 4 and args['large-keys'] == 0 and args['consumption'] == 'full',
         'This independent oracle qualifies only the declared full short-IRI growth fixtures')
    prefix, tail, width = args['prefix-probes'], args['tail-probes'], args['width']
    working, bootstrap = args['working-set'], args['bootstrap-keys']
    rows = (prefix + tail) // width
    def key_at(index):
        if args['pattern'] == 'cold-hot':
            return index if index < prefix else (index - prefix) % working
        need(args['pattern'] == 'warm-cycle', 'Unknown growth fixture pattern')
        return index % bootstrap if index < prefix else bootstrap + (index - prefix) % working
    key_count = prefix if args['pattern'] == 'cold-hot' else bootstrap + working
    lexical_hashes = []
    for key in range(key_count):
        text = f'urn:phase-memo:value:{key:08d}:'
        text += 'x' * (64 - len(text))
        value = 0
        for character in text:
            value = (value * 31 + ord(character)) & 0xffffffff
        lexical_hashes.append(value if value < 0x80000000 else value - 0x100000000)
    query = 'SELECT' + ''.join(' ?v' + str(column) for column in range(width)) + ' WHERE {\n'
    query += ''.join(f'  ?row <urn:phase-memo:p{column}> ?v{column} .\n' for column in range(width))
    query += '} ORDER BY ?row\n'
    recipe = hashlib.sha256(b'phase-memo-insertion-recipe-v1\n')
    checksum = 0
    for row in range(rows):
        folded = 0xcbf29ce484222325
        for column in range(width):
            key = key_at(row * width + column)
            for number in (row, column, key, 64):
                recipe.update(number.to_bytes(4, 'big', signed=True))
            folded = ((folded ^ (lexical_hashes[key] & MASK64)) * 0x100000001b3) & MASK64
        checksum = (checksum + folded * (row + 1)) & MASK64
    if checksum >= 1 << 63:
        checksum -= 1 << 64
    return {'expectedRows': rows, 'expectedConsumedRows': rows, 'expectedChecksum': str(checksum),
            'expectedConsumedChecksum': str(checksum), 'keyCount': key_count, 'statements': rows * width,
            'projectedOpportunities': rows * width, 'projectedLexicalChars': rows * width * 64,
            'query': query, 'querySha256': hashlib.sha256(query.encode('ascii')).hexdigest(),
            'insertionRecipeSha256': recipe.hexdigest()}


def inspect_tests(paths, memo_classes):
    need(len(paths) >= 6 and len(set(paths)) == len(paths), 'Supply every distinct final passing test group')
    groups, total = [], 0
    observed_cases = set()
    signatures = set()
    for receipt_path in paths:
        need(receipt_path.is_relative_to(PHASE / 'contracts/validation'), 'Use fresh growth test receipts')
        folder = receipt_path.parent
        receipt, inputs = read(receipt_path), read(folder / 'inputs.json')
        need(receipt['passed'] is True and receipt['moduleSourcesUnchanged'] is True
             and receipt['testProcessExit'] == 0 and receipt['expectedFailures'] == [], 'Test group did not pass')
        need(any(classes == memo_classes for classes in inputs['overlays'].values()),
             'Test group did not execute the selected memo class bytes')
        production = read(folder / 'production-class-files.json')
        need(all(production.get(name) == digest and sha(folder / 'classes' / name) == digest
                 for name, digest in memo_classes.items()), 'Executed memo classes differ from the final runtime')
        for source, digest in inputs['sources'].items():
            need(sha(source) == digest, 'A tested source changed after execution')
        totals = dict(tests=0, failures=0, errors=0, skipped=0)
        cases = []
        reports = sorted((folder / 'surefire-reports').glob('TEST-*.xml'))
        need(reports, 'Missing retained Surefire XML reports')
        for report in reports:
            suite = ET.parse(report).getroot()
            for key in totals:
                totals[key] += int(suite.attrib[key])
            for case in suite.findall('testcase'):
                failure, error = case.find('failure'), case.find('error')
                cases.append({'class': case.attrib['classname'], 'method': case.attrib['name'],
                              'failure': None if failure is None else failure.attrib.get('message', ''),
                              'error': None if error is None else error.attrib.get('message', '')})
        need(totals == receipt['results'] and totals['tests'] == len(cases) > 0
             and all(totals[key] == 0 for key in ('errors', 'failures', 'skipped')), 'Raw test totals did not pass')
        order = lambda case: (case['class'], case['method'])
        need(sorted(cases, key=order) == sorted(receipt['cases'], key=order), 'Receipt cases differ from raw XML')
        observed_cases.update((case['class'].split('.')[-1], case['method']) for case in cases)
        properties = dict(item.split('=', 1) for item in inputs['properties'])
        need(len(properties) == len(inputs['properties']), 'Duplicate test property')
        signature = tuple(properties.get('rdf4j.lmdb.nativeValueMemo.' + key, default)
                          for key, default in (('enabled', 'false'), ('retention', 'strong'),
                                               ('admission', 'initial'), ('growth', 'adaptive')))
        signatures.add((signature, totals['tests']))
        total += totals['tests']
        groups.append({'receipt': evidence(receipt_path), 'inputs': evidence(folder / 'inputs.json'),
                       'results': totals, 'properties': properties,
                       'rawReports': [evidence(report) for report in reports], 'memoClassBytesVerified': True})
    required = {(('false', 'strong', 'initial', 'adaptive'), 138),
                (('true', 'weak', 'initial', 'adaptive'), 47),
                (('true', 'weak', 'always', 'adaptive'), 28),
                (('true', 'weak', 'always', 'fixed'), 28)}
    need(required <= signatures, 'Missing default, weak, always/adaptive or always/fixed ownership qualification')
    contract_sources = [PHASE / 'contracts/test-src/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeDirectValueMemoGrowthContractTest.java',
                        PHASE.parent / 'admission-followup/contracts/test-src/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeDirectValueMemoAdmissionContractTest.java']
    for source in contract_sources:
        methods = set(re.findall(r'@Test\s+void\s+(\w+)\(', source.read_text()))
        need(methods and {(source.stem, method) for method in methods} <= observed_cases,
             'Missing complete admission/growth contract coverage')
    return {'qualifiedExecutions': total, 'identicalMemoClassFiles': len(memo_classes),
            'testGroups': groups, 'contractSources': [evidence(p) for p in contract_sources]}


def inspect_pilot(folder, arm, expected_fixture, classpath, memo_classes):
    args, expected = expected_fixture['arguments'], expected_fixture['expected']
    process, launch, validation = read(folder / 'process.json'), read(folder / 'command.json'), read(folder / 'pilot-validation.json')
    need(process['exitCode'] == 0 and process['timedOut'] is False and process['inputsUnchanged'] is True
         and process['comparisonSample'] is False
         and process['startedEpochNs'] == launch['startedEpochNs'] <= process['finishedEpochNs'], 'Pilot did not finish cleanly')
    need(all(sha(folder / name) == digest for name, digest in process['rawHashes'].items()), 'Pilot raw seal failed')
    need(validation['fixture'] == expected_fixture['id'] and validation['arm'] == arm
         and validation['exactOracleQualified'] is True and validation['comparisonSample'] is False
         and validation['queries'] == 13 and validation['independentExpected'] == expected, 'Wrong exact pilot receipt')
    command = launch['argv']
    cp_at = command.index('-cp')
    need(command[0] == str(runner.JAVA) and command[cp_at + 1] == ':'.join(classpath)
         and command[cp_at + 2] == runner.MAIN and launch['cwd'] == str(ROOT), 'Pilot JVM/classpath differs')
    properties = {runner.TRANSPORT: 'off', runner.ENABLED: str(arm != 'ordinary').lower(),
                  runner.RETENTION: 'weak', runner.ADMISSION: 'always',
                  runner.GROWTH: 'fixed' if arm == 'fixed' else 'adaptive'}
    need(Counter(command[1:cp_at]) == Counter(runner.JVM +
         ['-Xlog:gc:file=' + str(folder / 'gc.log') + ':uptime,level,tags'] +
         ['-D' + key + '=' + value for key, value in properties.items()]), 'Pilot JVM settings differ')
    cli = command[cp_at + 3:]
    parsed = dict(arg[2:].split('=', 1) for arg in cli)
    wanted = {key: str(value) for key, value in args.items()}
    wanted.update(arm=arm, source='growth-exact-pilot-v1', warmup='8', iterations='5', trace='false',
                  **{'exact-oracle': 'true', 'output': str(folder / 'samples.jsonl'), 'store': str(folder / 'store')})
    need(parsed == wanted and len(parsed) == len(cli), 'Pilot dimensions or consumer differ')
    inputs = read(folder / 'inputs.json')
    need(inputs[str(Path(classpath[1]))] == memo_classes, 'Pilot memo class bytes differ')
    records = analysis.json_lines(folder / 'samples.jsonl')
    need(len(records) == 15 and records[0]['type'] == 'metadata' and records[-1]['type'] == 'completion',
         'Expected metadata, thirteen exact queries and completion')
    metadata, samples, completion = records[0], records[1:-1], records[-1]
    analysis.subset(metadata, {**expected, **runner.CONFIG, **analysis.CALLER_METADATA,
        'arm': arm, 'source': parsed['source'], 'store': str(folder / 'store'), 'admission': 'always',
        'growth': properties[runner.GROWTH], 'trace': False, 'exactOracle': True,
        'oracleMode': 'exact-ordered-lexical', 'timingEligible': False, 'timingAccepted': False,
        'warmup': 8, 'measurementsToRun': 5, 'memoStatisticsCapacity': 13,
        'sourceCacheSettingsChanged': False, 'retainedOrderedRows': True, 'reopenedAfterPopulation': True,
        'maxHeapBytes': 1073741824, 'javaVersion': '25.0.5+8-LTS'}, 'Exact pilot metadata')
    need(metadata['jvmArguments'] == command[1:cp_at]
         and metadata['systemProperties'] == {'rdf4j.lmdb.hotCounters': 'true',
             'rdf4j.lmdb.queryMemory.perQueryMaxBytes': '536870912', **properties}, 'Observed pilot flags changed')
    width, rows = args['width'], expected['expectedRows']
    minimum_hits = (width - 1) * rows + width
    profile, observations = [], []
    for index, sample in enumerate(samples):
        analysis.subset(sample, {'type': 'sample', 'arm': arm, 'iteration': index - 8,
            'stage': 'warmup' if index < 8 else 'measurement', 'admission': 'always',
            'growth': properties[runner.GROWTH], 'consumption': 'full', 'rows': rows,
            'checksum': expected['expectedChecksum'], 'expectedChecksum': expected['expectedChecksum'],
            'expectedFullChecksum': expected['expectedChecksum'], 'projectedOpportunities': expected['projectedOpportunities'],
            'nativeProjectedRows': rows, 'projectedBindingSetsCreated': rows, 'retainedRows': 0,
            'ledgerBeforeBytes': 0, 'ledgerAfterBytes': 0, 'queryLedgerPeakBytes': None,
            'memoOverflowCount': 0, 'omittedSelections': 0, 'exactOracle': True,
            'oracleMode': 'exact-ordered-lexical', 'orderedExactLexicalOracleValid': True,
            'timingEligible': False, 'timingAccepted': False,
            **{key: True for key in ('valid', 'complete', 'rowCountValid', 'checksumValid', 'ledgerReleased',
                'memoLifecycleValid', 'autoRequested', 'auto', 'nativeRouteObserved', 'phaseCountersValid')}},
            'Exact result/lifetime oracle')
        analysis.inspect_phase_metrics(sample, True)
        analysis.subset(sample['counters'], {**analysis.ORDERED_COUNTERS, 'hostedGeneric': 0,
            'unhostedHardDeclines': 0, 'leftJoinReplayMaterializations': 0}, 'Actual ordered native execution')
        need(sample['successfulSelections'] == analysis.ORDERED_SELECTIONS, 'Expected normal ordered-factorized AUTO')
        adjacency, setup = sample['adjacency'], metadata['adjacencySetup']
        need(setup['state'] == adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
             and setup['currentRevisionReady'] is True
             and len({setup['appliedRevision'], setup['currentDataRevision'], adjacency['appliedRevisionBefore'],
                      adjacency['currentRevisionBefore'], adjacency['appliedRevisionAfter'],
                      adjacency['currentRevisionAfter']}) == 1, 'Adjacency is not current/active')
        need(adjacency['lookupHits'] == minimum_hits + int(index < 8) and adjacency['plannerStatsHits'] == 1
             and adjacency['exactMisses'] == 0 and adjacency['fallbacks'] == {},
             'Fresh full-sequence AUTO profile differs from the source-derived prediction')
        profile.append(analysis.route(sample))
        count = int(arm != 'ordinary')
        need(sample['memoOpenedDelta'] == sample['memoClosedDelta'] == len(sample['memoOwners']) == count,
             'Wrong pilot memo ownership')
        for owner in sample['memoOwners']:
            analysis.inspect_owner({'metadataReservation': {'arrayBase': 80, 'arrayPerSlot': 36,
                'weakMetadataPerSlot': 112, 'weakMetadataOverlap': 160}}, owner, sample, index, arm)
            need(owner['probes'] == sample['projectedOpportunities'], 'Enabled memo did not see the full exposure')
        hits = sum(owner['hits'] for owner in sample['memoOwners'])
        need(sample['projectedMaterializedValues'] + hits == sample['projectedOpportunities'],
             'Full exposure does not reconcile with observed hits')
        need(sample['counters']['lazyValueCalls'] == sample['projectedMaterializedValues']
             and sample['sourceLazyCallsAtPrefixBoundary'] == sample['projectedMaterializedValuesAtPrefixBoundary'],
             'Pilot source/projection scope changed')
        observations.append({key: sample[key] for key in ('iteration', 'rows', 'projectedOpportunities',
            'projectedMaterializedValues', 'sourceLazyCallsAtPrefixBoundary', 'memoOwners')})
    count = 13 * int(arm != 'ordinary')
    analysis.subset(completion, {'harnessReturned': True, 'queries': 13, 'warmups': 8, 'measurements': 5,
        'semanticNativeCompilesTotal': 13, 'hostedGenericTotal': 0, 'unhostedHardDeclinesTotal': 0,
        'memoOpenedTotal': count, 'memoClosedTotal': count, 'memoStatisticsSize': count,
        'memoOverflowCount': 0, 'ledgerAfterBytes': 0}, 'Pilot completion')
    analysis.gc_summary(folder / 'gc.log')
    return {'metadata': metadata, 'profile': profile, 'inputs': inputs,
            'interval': (process['startedEpochNs'], process['finishedEpochNs']),
            'receipt': {'fixture': expected_fixture['id'], 'arm': arm, 'queries': 13, 'comparisonSample': False,
                'evidence': [evidence(folder / name) for name in ('process.json', 'command.json', 'inputs.json',
                    'samples.jsonl', 'gc.log', 'pilot-validation.json')],
                'observedCountersNotPerformanceGates': observations}}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--classpath', required=True, type=Path)
    parser.add_argument('--pilot', required=True, action='append', type=Path)
    parser.add_argument('--test-receipt', required=True, action='append', type=Path)
    parser.add_argument('--definitions', type=Path, default=HERE / 'fixture-definitions-v1.json')
    parser.add_argument('--output', type=Path, default=HERE / 'qualification/final-runtime-v1.json')
    parser.add_argument('--baseline-classes', type=Path, default=PHASE.parent /
                        'retention-followup/recovery/runtime-v1/baseline/artifacts/001-classes')
    args = parser.parse_args()
    definitions_path, qualification_path = args.definitions.resolve(), args.output.resolve()
    need(not definitions_path.exists() and not qualification_path.exists(), 'Preserve existing qualification outputs')
    oracle_path = HERE / 'fixture-oracles-v1.json'
    oracle_document = read(oracle_path)
    need(sha(HERE / 'fixture_oracle.py') == oracle_document['oracleSourceSha256'], 'Independent oracle source changed')
    fixtures = {item['id']: item for item in oracle_document['fixtures']}
    need(tuple(fixtures) == analysis.FIXTURE_IDS, 'Wrong prospectively selected fixtures')
    for fixture in fixtures.values():
        analysis.subset(fixture['expected'], direct_oracle(fixture['arguments']), 'Independent full-string oracle')
    cp_file = args.classpath.resolve(strict=True)
    classpath, runtime_inputs = runner.classpath_inputs(cp_file)
    need(classpath[0] == str(cp_file.parent / 'classes') and len(classpath) > 2, 'Final harness is not first in classpath')
    memo_root = Path(classpath[1]).parent
    memo_classes = class_hashes(memo_root / 'classes')
    need(memo_root.is_relative_to(PHASE) and memo_classes
         and memo_classes == read(memo_root / 'class-files.json'), 'Memo prefix identity failed')
    ownership = inspect_tests([path.resolve(strict=True) for path in args.test_receipt], memo_classes)
    baseline = class_hashes(args.baseline_classes.resolve(strict=True))
    current = class_hashes(ROOT / 'core/sail/lmdb/target/classes')
    need(baseline and baseline == current, 'Fresh root LMDB classes differ from the preserved baseline')
    harness_receipt_path = cp_file.parent / 'compile-receipt.json'
    harness_receipt = read(harness_receipt_path)
    harness_manifest = cp_file.parent / 'class-files.json'
    need(harness_receipt['compiled'] is True and harness_receipt['classpathSha256'] == sha(cp_file)
         and harness_receipt['classFilesSha256'] == sha(harness_manifest)
         and class_hashes(cp_file.parent / 'classes') == read(harness_manifest)
         and all(sha(path) == digest for path, digest in harness_receipt['sourceHashes'].items()),
         'Final harness compilation identity failed')
    pilot_folders = [path.resolve(strict=True) for path in args.pilot]
    need(len(pilot_folders) == len(set(pilot_folders)) == 9, 'Exactly nine fresh full pilots are required')
    indexed = {}
    for folder in pilot_folders:
        need(folder.is_relative_to(HERE / 'qualification'), 'Use fresh growth pilot paths')
        validation = read(folder / 'pilot-validation.json')
        key = (validation['fixture'], validation['arm'])
        need(key not in indexed and key[0] in fixtures and key[1] in runner.ARMS, 'Extra or repeated pilot')
        indexed[key] = inspect_pilot(folder, key[1], fixtures[key[0]], classpath, memo_classes)
    definitions, pilots, profiles, intervals = [], [], {}, []
    first_inputs = None
    for fixture_id, fixture in fixtures.items():
        expected = fixture['expected']
        matched_metadata = matched_profile = None
        for arm in runner.ARMS:
            pilot = indexed[fixture_id, arm]
            normalized = analysis.normalized_metadata(pilot['metadata'])
            matched_metadata = normalized if matched_metadata is None else matched_metadata
            need(normalized == matched_metadata, 'Cross-arm exact fixture metadata differs')
            matched_profile = pilot['profile'] if matched_profile is None else matched_profile
            need(pilot['profile'] == matched_profile, 'Per-ordinal AUTO route differs across arms')
            first_inputs = pilot['inputs'] if first_inputs is None else first_inputs
            need(pilot['inputs'] == first_inputs, 'Exact pilot input identity differs')
            pilots.append(pilot['receipt'])
            intervals.append(pilot['interval'])
        profiles[fixture_id] = matched_profile
        minimum = (fixture['arguments']['width'] - 1) * expected['expectedRows'] + fixture['arguments']['width']
        definitions.append({'id': fixture_id, 'arguments': fixture['arguments'], 'metadata': expected,
            'oracle': {'rows': expected['expectedConsumedRows'], 'fullRows': expected['expectedRows'],
                       'checksum': expected['expectedConsumedChecksum'], 'fullChecksum': expected['expectedChecksum']},
            'qualification': {'measuredTier': 'ordered-factorized', 'minimumAdjacencyLookupHits': minimum,
                'adjacencyExplanation': 'Fresh full 13-query exact pilots reproduce the source-derived floor '
                    '(width-1)*rows+width and the extra root adjacency hit during queries 1-8. Queries 9-13 '
                    'normally sample the LMDB root alternative. This is matched AUTO learning, not converged '
                    'source selection. All three growth arms reproduce the complete same-ordinal profile.',
                'sampleCounters': {key: matched_profile[0]['counters'][key] for key in analysis.ROUTE_COUNTERS},
                'projection': {'nativeProjectedRows': expected['expectedRows'],
                               'projectedBindingSetsCreated': expected['expectedRows']}}})
    intervals.sort()
    need(all(left[1] <= right[0] for left, right in zip(intervals, intervals[1:])), 'Pilot JVM intervals overlap')
    for raw_path, expected in first_inputs.items():
        path = Path(raw_path)
        actual = sha(path) if isinstance(expected, str) else {
            p.relative_to(path).as_posix(): sha(p) for p in path.rglob('*') if p.is_file()}
        need(actual == expected, 'A pilot input changed after execution: ' + raw_path)
    document = {'format': 1, 'fixtures': definitions}
    analysis.validate_definitions(document)
    runner.write(definitions_path, document)
    jdk = runner.jdk_inputs(runner.JAVA)
    qualification = {'format': 'growth-final-runtime-qualification-v1',
        'createdUtc': datetime.now(timezone.utc).isoformat(), 'qualifiedForTiming': True,
        'exactOracleQualified': True, 'fixtureDefinitionsSha256': sha(definitions_path),
        'classpathFileSha256': sha(cp_file), 'runtimeInputsSha256': analysis.object_sha(runtime_inputs),
        'javaSha256': sha(runner.JAVA), 'jdkInputsSha256': analysis.object_sha(jdk),
        'java': str(runner.JAVA), 'classpathFile': str(cp_file), 'builder': evidence(Path(__file__)),
        'reviewedScripts': {name: sha(HERE / name) for name in
                            ('run_comparison.py', 'analyze_comparison.py', 'check_route_profile.py', 'run_pilot.py')},
        'independentOracle': evidence(oracle_path), 'ownership': ownership,
        'rootBaseline': {'currentClasses': str(ROOT / 'core/sail/lmdb/target/classes'),
                         'preservedClasses': str(args.baseline_classes.resolve()), 'identicalClassFiles': len(current),
                         'independentlyRehashedClassMapSha256': analysis.object_sha(current)},
        'harnessCompilation': evidence(harness_receipt_path), 'pilotJvms': 9, 'exactQueryExecutions': 117,
        'pilots': pilots, 'comparisonSamples': 0, 'qualifiedRouteProfiles': profiles,
        'qualifiedRouteProfilesSha256': analysis.object_sha(profiles),
        'profileChecker': evidence(HERE / 'check_route_profile.py'),
        'scope': 'Fresh growth contracts/ownership checks and all nine complete exact pilots qualify these bytes. '
                 'The 8+5 sequence and memo statistics capacity match the future timing cohort. Final queries '
                 'remain in normal AUTO alternative-source learning. Pilot latency/allocation values are not '
                 'analyzed to choose fixtures, tune growth, discard observations or enter the latency cohort. '
                 'Equal late-case reuse is a hypothesis and never a qualification gate.',
        'memoryScope': 'Process-authority ledger and memo metadata estimates; no separate active-query peak '
                       'or whole-heap/native memory bound.',
        'callerPhaseScope': analysis.CALLER_METADATA['callerPhaseScope'],
        'callerCpuScope': analysis.CALLER_METADATA['callerCpuScope'],
        'retentionRestriction': 'Ordered wrappers may retain consumed Values. No useful-key weak collection '
                                'or physical source-decode claim.', 'javaLaunchesByThisBuilder': 0}
    qualification_path.parent.mkdir(parents=True, exist_ok=True)
    runner.write(qualification_path, qualification)
    print(json.dumps({'fixtureDefinitions': evidence(definitions_path), 'qualification': evidence(qualification_path),
                      'pilotJvms': 9, 'exactQueryExecutions': 117,
                      'qualifiedExecutions': ownership['qualifiedExecutions'],
                      'runtimeInputsSha256': qualification['runtimeInputsSha256']}))


if __name__ == '__main__':
    main()
